"""Compute the order of the permutation group generated by the Maltese move tables.

Point set (192 points):
    0..95     sticker positions
    96..191   gear orientations: gear slot j with orientation r  ->  96 + 4*j + r

A move is a permutation of these points. Gear colours are attributes that travel
with the gear, so they add no extra points. The result is |G| for the
position-permutation group; the number of distinct coloured states reachable from
the goal is |G| / |Stab(goal)| and is at most |G|.
"""
from __future__ import annotations

import sys
import time
from pathlib import Path

import numpy as np

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from puzzles.maltese_gear.puzzle import build_maltese_gear_puzzle  # noqa: E402

N_STICKER = 96
N_SLOT = 24
N_POINTS = N_STICKER + 4 * N_SLOT  # 192


def point_permutations(puzzle) -> list[list[int]]:
    perms: list[list[int]] = []
    for m in range(puzzle.num_moves):
        idx = puzzle.idx[m]
        add = puzzle.add[m]
        arr = np.full(N_POINTS, -1, dtype=np.int64)
        # Sticker content at source position idx[i] moves to destination i.
        for i in range(N_STICKER):
            arr[idx[i]] = i
        # Gear slot j receives the gear from slot k = idx[120 + j] - 120, with the
        # orientation shifted by add[120 + j].
        for j in range(N_SLOT):
            k = int(idx[120 + j]) - 120
            a = int(add[120 + j])
            for r in range(4):
                arr[N_STICKER + 4 * k + r] = N_STICKER + 4 * j + ((r + a) % 4)
        assert sorted(arr.tolist()) == list(range(N_POINTS)), f"move {m} is not a permutation"
        perms.append(arr.tolist())
    return perms


def main() -> None:
    from sympy.combinatorics import Permutation, PermutationGroup

    puzzle = build_maltese_gear_puzzle()
    gens = [Permutation(p) for p in point_permutations(puzzle)]
    t0 = time.time()
    group = PermutationGroup(gens)
    order = group.order()
    elapsed = time.time() - t0
    print(f"degree {N_POINTS}, generators {len(gens)}")
    print(f"|G| = {order}")
    print(f"log10|G| = {np.log10(float(order)):.3f}")
    print(f"time {elapsed:.1f}s")


if __name__ == "__main__":
    main()
